WITH kept_keys AS (SELECT id FROM transactions INTERSECT SELECT id FROM transactions WHERE is_flagged), reconciled AS (SELECT s.* FROM transactions s INNER JOIN kept_keys k ON s.id = k.id) SELECT s.id, s.account_id, s.txn_type, s.amount, s.txn_time, s.merchant, s.is_flagged, (SELECT AVG(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS avg_transaction_amount FROM reconciled s ORDER BY account_id
